#define C(x) do{int e=(x);if(e){fprintf(stderr,"CUDAerror%d line%d\n",e,__LINE__);exit(1);}}while(0)
template<class A>std::vector<A>read(const std::string&p,int n=-1){std::ifstream f(p,std::ios::binary|std::ios::ate);if(n<0)n=f.tellg()/sizeof(A);f.seekg(0);std::vector<A>a(n);f.read((char*)a.data(),n*sizeof(A));if(f.gcount()!=n*sizeof(A))exit(2);return a;}
template<class A>struct Buffer{A*base,*ptr;std::vector<A>initial;Buffer(std::vector<A>x,A guard){initial.assign(16,guard);initial.insert(initial.end(),x.begin(),x.end());initial.insert(initial.end(),16,guard);C(cudaMalloc(&base,initial.size()*sizeof(A)));ptr=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*sizeof(A),cudaMemcpyHostToDevice));}void append(std::vector<int>&out){std::vector<A>a(initial.size());C(cudaMemcpy(a.data(),base,a.size()*sizeof(A),cudaMemcpyDeviceToHost));for(A v:a)out.push_back(v);}~Buffer(){cudaFree(base);}};
struct Corpus{int id,n,bytes;Buffer<char>text;Buffer<unsigned>offset;std::vector<Buffer<unsigned char>*>results;Corpus(int i):id(i),n(i==0?1:i==1?4770:81923),bytes(i==0?6:i==1?144355:424072),text(read<char>("text"+std::to_string(i)+"_u8.bin"),char(211)),offset(read<unsigned>("offset"+std::to_string(i)+"_u32.bin"),1234567){for(int j=0;j<PATTERNS;j++)results.push_back(new Buffer<unsigned char>(std::vector<unsigned char>(n,0),211));}};
// Separate genuinepostfix/NFA observer, not primarytimedkernelintermediatecapture.
__global__ void observe_graph(char*regex,unsigned*rt,State*match,int*out){__shared__ char buf[BUFFER_SIZE];__shared__ State states[100];__shared__ int count;__shared__ State*start;if(threadIdx.x==0){pre2post(regex+rt[0],buf);count=0;start=ppost2nfa(buf,states,&count,match);}__syncthreads();if(threadIdx.x==0){int b=blockIdx.x*404;int len=pstrlen(buf);out[b]=len;out[b+1]=count;out[b+2]=start?int(start-states)+1:0;for(int i=0;i<=len&&i<100;i++)out[b+3+i]=(unsigned char)buf[i];for(int i=0;i<count;i++){State*a=states[i].out,*c=states[i].out1;out[b+103+i*3]=states[i].c;out[b+104+i*3]=a==NULL?0:a==match?101:int(a-states)+1;out[b+105+i*3]=c==NULL?0:c==match?101:int(c-states)+1;}}}
int main(int argc,char**argv){auto expected=read<int>("oracle_i32.bin",COUNT);std::vector<Corpus*>cs;for(int k=0;k<CASES;k++)cs.push_back(new Corpus(k));std::vector<Buffer<char>*>regex;for(int j=0;j<PATTERNS;j++)regex.push_back(new Buffer<char>(read<char>("regex"+std::to_string(j)+"_u8.bin"),char(211)));Buffer<unsigned>rt({0},1234567);State hmatch={};hmatch.c=Match;State*match;C(cudaMalloc(&match,sizeof(State)));C(cudaMemcpy(match,&hmatch,sizeof(State),cudaMemcpyHostToDevice));auto reset=[&](){for(auto c:cs)for(auto o:c->results)o->reset();};auto pipeline=[&](){for(auto c:cs)for(int j=0;j<PATTERNS;j++)parallelMatch<<<512,160>>>(c->text.ptr,c->offset.ptr,c->n,regex[j]->ptr,rt.ptr,c->results[j]->ptr,match);C(cudaGetLastError());C(cudaDeviceSynchronize());};auto prefix=[&](std::vector<int>&out){State actual;C(cudaMemcpy(&actual,match,sizeof(State),cudaMemcpyDeviceToHost));out={3,10,512,160,100,1000,8000,actual.c};for(int j=0;j<PATTERNS;j++){out.push_back(j);out.push_back(regex[j]->initial.size()-32);std::vector<char>h(regex[j]->initial.size());C(cudaMemcpy(h.data(),regex[j]->base,h.size(),cudaMemcpyDeviceToHost));for(char v:h)out.push_back((unsigned char)v);}for(auto c:cs){out.insert(out.end(),{c->id,c->n,c->bytes});std::vector<char>h(c->text.initial.size());C(cudaMemcpy(h.data(),c->text.base,h.size(),cudaMemcpyDeviceToHost));for(char v:h)out.push_back((unsigned char)v);c->offset.append(out);for(auto o:c->results)o->append(out);}};pipeline();for(int trial=1;trial<=5;trial++){reset();std::vector<int>out;prefix(out);if(out.size()!=PREFIX){fprintf(stderr,"prefix%zu wanted%d\n",out.size(),PREFIX);return 3;}C(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();pipeline();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();for(auto c:cs)for(auto o:c->results)o->append(out);bool good=out==expected;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/grep_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%s,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"30resident_full_GPU_regex_postfix_NFAcompile_and_fullmatch_completion\",\"internal_repeats\":1,\"iterations\":1,\"kernel_launches\":30,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,good?"true":"false",out.size(),good?"0":"null",path.c_str(),out.size());fflush(stdout);if(!good){for(int i=0;i<COUNT;i++)if(out[i]!=expected[i]){fprintf(stderr,"mismatchat%d actual%d expected%d\n",i,out[i],expected[i]);break;}return 4;}}
std::filesystem::create_directories(argv[1]);for(int j=0;j<PATTERNS;j++){Buffer<int>g(std::vector<int>(512*404,-999),-12345);observe_graph<<<512,160>>>(regex[j]->ptr,rt.ptr,match,g.ptr);C(cudaGetLastError());C(cudaDeviceSynchronize());std::vector<int>trace;g.append(trace);std::string path=std::string(argv[1])+"/actual_graph_"+std::to_string(j)+"_"+std::to_string(getpid())+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)trace.data(),trace.size()*4);printf("STUDY_AUXILIARY actual_untimed_NFA_graph pattern=%d values=%zu path=%s\n",j,trace.size(),path.c_str());}return 0;}
